// Physical imported targets, pending indirect-call arguments, and cached module/thread pointers retain original reload order.
using System;namespace Recovered.Gameplay {public static class PtlThreadCodec {public static uint Decode(SoundSetupImage m,uint encoded,Func<SoundSetupImage,uint,uint[],uint> call){uint slot=m.Word(0x829ab8),tlsGet=m.Word(0x7511bc);uint decoder=0;bool cached=false;if(call(m,tlsGet,new uint[]{slot})!=0){uint index=m.Word(0x829ab4);if(index!=0xffffffff){uint secondSlot=m.Word(0x829ab8);uint getter=call(m,tlsGet,new uint[]{secondSlot});uint thread=call(m,getter,new uint[]{index});if(thread!=0){decoder=m.Word(thread+0x1fc);cached=true;}}}if(!cached){uint module=call(m,m.Word(0x751154),new uint[]{0x777fd8});if(module!=0&&call(m,0x6f00d9,new uint[0])!=0)decoder=call(m,m.Word(0x7511b0),new uint[]{module,0x777fe8});}return decoder==0?encoded:call(m,decoder,new uint[]{encoded});}public static uint Getter(SoundSetupImage m,Func<SoundSetupImage,uint,uint[],uint> call){uint slot=m.Word(0x829ab8),getter=call(m,m.Word(0x7511bc),new uint[]{slot});if(getter==0){getter=Decode(m,m.Word(0x297c53c),call);uint setSlot=m.Word(0x829ab8);call(m,m.Word(0x7511c4),new uint[]{setSlot,getter});}return getter;}public static uint Get(SoundSetupImage m,Func<SoundSetupImage,uint,uint[],uint> call){return PtlThreadNoExit.Get(m,delegate(SoundSetupImage image,uint address,uint[] values){if(address==0x6f024e)return Getter(image,call);if(address==0x6f01bc)return Decode(image,values[0],call);return call(image,address,values);});}}}
